package com.nexbank.fraud.web;
import com.fasterxml.jackson.databind.ObjectMapper;import com.nexbank.fraud.entity.FraudAlert;import com.nexbank.fraud.repository.FraudAlertRepository;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.time.Instant;import java.util.*;
@RestController @RequestMapping("/api/fraud/alerts") public class FraudController {private final FraudAlertRepository alerts;private final JdbcTemplate jdbc;private final ObjectMapper mapper;public FraudController(FraudAlertRepository a,JdbcTemplate j,ObjectMapper m){alerts=a;jdbc=j;mapper=m;}
 @GetMapping public List<FraudAlert> list(@RequestHeader(value="X-User-Role",defaultValue="")String role){require(role);return alerts.findByStatusOrderByCreatedAtDesc("NEW");}
 @PutMapping("/{id}/review") @Transactional public FraudAlert review(@PathVariable UUID id,@RequestHeader("X-User-Id")UUID actor,@RequestHeader(value="X-User-Role",defaultValue="")String role,@RequestParam String decision){require(role);if(!Set.of("CLEARED","BLOCKED").contains(decision))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"decision must be CLEARED or BLOCKED");FraudAlert a=alerts.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(decision.equals("BLOCKED")&&a.getUserId()==null)throw new ResponseStatusException(HttpStatus.CONFLICT,"Alert does not have an account owner associated");a.review(decision,actor);a=alerts.save(a);if(decision.equals("BLOCKED")){try{UUID eventId=UUID.randomUUID();String payload=mapper.writeValueAsString(Map.of("eventId",eventId,"eventType","account-freeze-requested","accountId",a.getAccountId(),"userId",a.getUserId(),"reason","compliance-blocked","timestamp",Instant.now().toString()));jdbc.update("insert into fraud_outbox_events(id,event_type,aggregate_id,payload) values (?,?,?,cast(? as jsonb))",eventId,"account-freeze-requested",a.getAccountId(),payload);}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw new IllegalStateException("Could not serialize freeze request",e);}}return a;}
 private void require(String role){if(!role.equals("ADMIN")&&!role.equals("COMPLIANCE_OFFICER"))throw new ResponseStatusException(HttpStatus.FORBIDDEN);}}
